import type { AcpMessage, JsonRpcError } from './json-rpc.js'

// ─── bridge/hello (Request/Response) ──────────────────────────────────────────

/** Parameters sent by the agent-side adapter in the bridge/hello request */
export interface BridgeHelloParams {
  /** Authentication token (issued by host app) */
  token: string

  /**
   * Globally unique agent identifier, generated by the agent-side adapter.
   * Format: "<hostname>:<executable>:<cwd-basename>:<8-char-uuid>"
   * Example: "dev-laptop:node:my-project:f47ac10b"
   *
   * Stable across WebSocket reconnections (same bridge process).
   * Changes when the bridge process restarts.
   */
  agentId: string

  /**
   * Connection mode. Defaults to 'bridge' for backward compatibility.
   * - 'bridge': standard mode — agent already spawned, relay ACP messages
   * - 'daemon': daemon mode — no agent yet, waits for spawn commands
   */
  mode?: 'bridge' | 'daemon'

  /** Bridge (agent-side adapter) identity */
  bridge: {
    /** Bridge name, always "agentlet" */
    name: string
    /** Bridge version (semver) */
    version: string
  }

  /** Spawned agent process info (required for mode='bridge', absent for mode='daemon') */
  agent?: {
    /** Shell command used to spawn the agent */
    command: string
    /** OS process ID of the agent */
    pid: number
    /** Working directory of the agent process */
    cwd: string
  }

  /**
   * Active ACP session info (present when agentlet has completed session bootstrap).
   * In bridge mode, this is always present after startup.
   * In daemon mode, each spawned agent reports its own session via a separate bridge/hello.
   */
  session?: {
    /** The active ACP sessionId */
    sessionId: string
    /** Whether the agent supports session/load (from initializeResult.agentCapabilities.loadSession) */
    supportsLoad: boolean
    /** The full ACP initialize response (agent capabilities, info, protocol version) */
    initializeResult: unknown
  }

  /** Machine info (informational, for display/debugging) */
  machine?: {
    /** os.hostname() */
    hostname: string
    /** "win32" | "darwin" | "linux" */
    platform: string
  }

  /** Bridge capabilities */
  capabilities: {
    /** Whether --auto-restart is enabled */
    autoRestart: boolean
    /** Max messages buffered during disconnect */
    bufferLimit: number
    /** Max concurrent agents (daemon mode only) */
    maxAgents?: number
  }
}

/** Success result returned by the server after bridge/hello */
export interface BridgeHelloResult {
  /** Echoed back agentId confirming registration */
  agentId: string
  /** Connection status */
  status: 'connected'
}

/** Error returned by the server when bridge/hello fails */
export type BridgeHelloError = JsonRpcError

// ─── Bridge Control Notifications: Agent-side → Server ────────────────────────

/** Sent when the agent process exits */
export interface BridgeAgentExitedParams {
  /** Exit code (null if killed by signal) */
  code: number | null
  /** Signal name, e.g. "SIGTERM" (null if normal exit) */
  signal: string | null
  /** Whether auto-restart will attempt recovery */
  willRestart: boolean
}

/** Sent when the agent is successfully restarted after a crash */
export interface BridgeAgentRestartedParams {
  /** New agent process ID */
  pid: number
  /** Restart attempt number (1-based) */
  attempt: number
}

/** Sent when the bridge is shutting down gracefully */
export interface BridgeGoodbyeParams {
  /** Reason for shutdown */
  reason: 'user_interrupt' | 'server_requested' | 'max_restarts_exceeded' | (string & {})
}

/** Sent when the buffer limit is reached during disconnect */
export interface BridgeBufferOverflowParams {
  /** Number of oldest messages dropped */
  dropped: number
}

// ─── Bridge Control Notifications: Server → Agent-side ────────────────────────

/** Sent by server after reconnection to replay buffered messages */
export interface BridgeReplayParams {
  /** ACP messages buffered by the server while agent was disconnected */
  messages: AcpMessage[]
}

/** Application-level keepalive ping from server */
export interface BridgePingParams {}

/** Response to bridge/ping */
export interface BridgePongParams {}

/** Server requests agent-side adapter to shut down */
export interface BridgeShutdownParams {
  /** Reason for shutdown request */
  reason: 'token_revoked' | 'server_shutting_down' | 'idle_timeout' | (string & {})
}

// ─── Daemon Control Messages (Server → Daemon) ───────────────────────────────

/** Server requests daemon to spawn an agent */
export interface DaemonSpawnParams {
  /** Shell command to spawn the agent (must support ACP stdio) */
  command: string
  /** Working directory for the agent subprocess */
  cwd?: string
  /** Extra environment variables for the agent */
  env?: Record<string, string>
  /** Whether to auto-restart the agent on crash */
  autoRestart?: boolean
}

/** Successful spawn result returned by daemon */
export interface DaemonSpawnResult {
  /** The agentId of the newly spawned agent */
  agentId: string
  /** The OS process ID of the agent */
  pid: number
}

/** Server requests daemon to stop a running agent */
export interface DaemonStopParams {
  /** The agentId of the agent to stop */
  agentId: string
}

/** Successful stop result returned by daemon */
export interface DaemonStopResult {
  /** Whether the agent was successfully stopped */
  stopped: boolean
}

/** Server requests daemon to list its running agents */
export interface DaemonListParams {}

/** Daemon's response to bridge/list with running agents */
export interface DaemonListResult {
  agents: Array<{
    agentId: string
    command: string
    pid: number
    cwd: string
    status: 'running' | 'starting'
  }>
}

// ─── Daemon Connection Info (surfaced to host app) ────────────────────────────

/** Represents a connected daemon in the server registry */
export interface DaemonConnection {
  readonly daemonId: string
  readonly token: string
  readonly metadata: Record<string, unknown>
  readonly machine?: { hostname: string; platform: string }
  readonly bridge: { name: string; version: string }
  readonly capabilities: { autoRestart: boolean; bufferLimit: number; maxAgents?: number }
  readonly status: 'connected' | 'disconnected'
  readonly connectedAt: Date
  readonly agents: string[]
}

// ─── Lifecycle Events (surfaced to host app) ──────────────────────────────────

/** Union of all lifecycle events the server surfaces to the host app */
export type BridgeLifecycleEvent =
  | { type: 'agent_exited'; code: number | null; signal: string | null; willRestart: boolean }
  | { type: 'agent_restarted'; pid: number; attempt: number }
  | { type: 'buffer_overflow'; dropped: number }
  | { type: 'goodbye'; reason: string }
